import * as React from "react";
import { cx } from "./cx";

export interface Crumb {
  label: React.ReactNode;
  href?: string;
}

export interface BreadcrumbsProps extends React.HTMLAttributes<HTMLElement> {
  items: Crumb[];
}

export function Breadcrumbs({ items, className, ...props }: BreadcrumbsProps) {
  return (
    <nav aria-label="Breadcrumbs" className={cx("rs-crumbs", className)} {...props}>
      {items.map((item, index) => {
        const last = index === items.length - 1;
        return (
          <React.Fragment key={index}>
            {index > 0 && (
              <span className="rs-crumbs-sep" aria-hidden="true">
                /
              </span>
            )}
            {last ? (
              <span className="rs-crumbs-here" aria-current="page">
                {item.label}
              </span>
            ) : item.href ? (
              <a className="rs-crumbs-link" href={item.href}>
                {item.label}
              </a>
            ) : (
              <span>{item.label}</span>
            )}
          </React.Fragment>
        );
      })}
    </nav>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Breadcrumbs: one ink trail. Slashes at 40%. Current page is full ink.
   Ancestors stay Inter/ink — never a UA :link or :visited color, never an accent. ── */
.rs-crumbs{font-size:13px;color:var(--text);letter-spacing:-.01em;display:flex;align-items:baseline;gap:8px}
.rs-crumbs a,
.rs-crumbs a:link,
.rs-crumbs a:visited,
.rs-crumbs a:hover,
.rs-crumbs a:active,
.rs-crumbs a:focus,
.rs-crumbs a:focus-visible,
.rs-crumbs a:any-link,
.rs-crumbs a:-webkit-any-link,
.rs-crumbs .rs-crumbs-link{
  color:var(--text);
  text-decoration:none;
  background:none;
}
.rs-crumbs a,
.rs-crumbs a:link,
.rs-crumbs a:visited,
.rs-crumbs a:any-link,
.rs-crumbs a:-webkit-any-link,
.rs-crumbs .rs-crumbs-link{opacity:.55}
.rs-crumbs a:hover,.rs-crumbs a:focus-visible{opacity:1}
.rs-crumbs-sep{color:var(--text);opacity:.4}
.rs-crumbs-here{color:var(--text);opacity:1}
